const getRandomSellerForCountry = (countryCode) => {
  const code = String(countryCode || '').toUpperCase();
  const list = RANDOM_SELLER_NAMES[code] || RANDOM_SELLER_NAMES.default;
  return list[Math.floor(Math.random() * list.length)];
};

