const ALL_COUNTRY_DEFS = CONTINENTS.flatMap((c) =>
  c.countries.map((co) => ({ ...co, continentId: c.id }))
);

const resolveCountryCodeFromLocation = (locationStr, explicitCode) => {
  if (explicitCode) {
    const code = String(explicitCode).toUpperCase();
    if (ALL_COUNTRY_DEFS.some((c) => c.code === code)) return code;
  }
  const loc = String(locationStr || '').toLowerCase();
  if (!loc.trim()) return null;
  // Prefer longer keywords first
  const ranked = ALL_COUNTRY_DEFS.flatMap((c) =>
    (c.keywords || []).map((kw) => ({ code: c.code, kw, len: kw.length }))
  ).sort((a, b) => b.len - a.len);
  for (const { code, kw } of ranked) {
    if (loc.includes(kw)) return code;
  }
  return null;
};

