  useEffect(() => {
    if (!showFakeMapModal) return;
    let map;
    let marker;
    let cancelled = false;

    const initTimer = setTimeout(async () => {
      try {
        await loadLeafletAssets();
      } catch (e) {
        if (!cancelled) alert('⚠️ ' + t('mapLoadError'));
        return;
      }
      if (cancelled || !fakeMapContainerRef.current || !window.L) return;
      const L = window.L;
      if (L.Icon && L.Icon.Default && L.Icon.Default.prototype) {
        delete L.Icon.Default.prototype._getIconUrl;
        L.Icon.Default.mergeOptions({
          iconRetinaUrl:
            'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
          iconUrl:
            'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
          shadowUrl:
            'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
        });
      }
      const startLat = fakeMapPick?.lat ?? 22;
      const startLon = fakeMapPick?.lon ?? 8;
      const startZoom = fakeMapPick ? 6 : 2;
      map = L.map(fakeMapContainerRef.current, { worldCopyJump: true }).setView(
        [startLat, startLon],
        startZoom
      );
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap contributors',
        maxZoom: 19,
      }).addTo(map);
      if (fakeMapPick?.lat != null && fakeMapPick?.lon != null) {
        marker = L.marker([fakeMapPick.lat, fakeMapPick.lon]).addTo(map);
      }
      map.on('click', async (e) => {
        const lat = e.latlng.lat;
        const lng = e.latlng.lng;
        if (marker) marker.setLatLng([lat, lng]);
        else marker = L.marker([lat, lng]).addTo(map);
        setFakeMapLoading(true);
        try {
          const geo = await reverseGeocodePoint(lat, lng);
          const currency =
            getCurrencyFromCountryCode(geo.countryCode) || CURRENCIES.EUR;
          const lang = getLangFromCountryCode(geo.countryCode);
          setFakeMapPick({ ...geo, currency, lang });
        } catch (err) {
          setFakeMapPick({
            lat,
            lon: lng,
            city: '',
            country: '',
            countryCode: '',
            location: `${lat.toFixed(4)}, ${lng.toFixed(4)}`,
            currency: CURRENCIES.EUR,
            lang: 'en',
          });
        }
        setFakeMapLoading(false);
      });
      setTimeout(() => {
        if (map) map.invalidateSize();
      }, 250);
    }, 80);

    return () => {
      cancelled = true;
      clearTimeout(initTimer);
      if (map) {
        map.off();
        map.remove();
      }
    };
  }, [showFakeMapModal]);

