  const handleRatingSubmit = (purchaseItem, sellerName) => {
    const ratingValue = Number(ratingStars) || 5;
    const commentValue = ratingComment.trim() || '¡Todo excelente!';

    let currentUsers = users;
    try {
      const savedU = localStorage.getItem('pokepop_users');
      if (savedU) currentUsers = JSON.parse(savedU);
    } catch (e) {}

    const targetUser = currentUsers[sellerName] || {
      name: sellerName,
      displayName: sellerName,
      location: 'España',
      rating: 5.0,
      reviews: [],
    };

    const newReview = {
      reviewer: displayTrainerName,
      rating: ratingValue,
      comment: commentValue,
      time: 'justNow',
    };

    const updatedReviews = [newReview, ...(targetUser.reviews || [])];
    const totalRatingSum = updatedReviews.reduce((acc, r) => acc + r.rating, 0);
    const newAvgRating = Number(
      (totalRatingSum / updatedReviews.length).toFixed(1)
    );

    const updatedTargetUser = {
      ...targetUser,
      rating: newAvgRating,
      reviews: updatedReviews,
    };

    const nextUsers = { ...currentUsers, [sellerName]: updatedTargetUser };
    setUsers(nextUsers);
    localStorage.setItem('pokepop_users', JSON.stringify(nextUsers));

    let freshHistory = purchasesHistory;
    try {
      const sH = localStorage.getItem('pokepop_global_purchases_history');
      if (sH) freshHistory = JSON.parse(sH);
    } catch (e) {}

    const nextHistory = [{ ...purchaseItem, rated: true }, ...freshHistory];

    let freshConfirmed = confirmedPurchases;
    try {
      const sC = localStorage.getItem('pokepop_global_purchases');
      if (sC) freshConfirmed = JSON.parse(sC);
    } catch (e) {}

    const nextConfirmed = freshConfirmed.filter(
      (p) => p.id !== purchaseItem.id
    );

    saveToStorage(null, nextConfirmed, nextHistory, null);
    setRatingTargetSeller(null);
    setRatingComment('');
    alert(
      `⭐ ¡Valoración enviada con éxito! El vendedor ha sumado una venta confirmada.`
    );
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setAuthError('');
    const cleanEmail = String(loginEmail || '')
      .trim()
      .toLowerCase();
    if (!cleanEmail || !loginPassword) return;

    if (bannedEmails.map((e) => String(e).toLowerCase()).includes(cleanEmail)) {
      setAuthError(
        '🚫 Este correo está baneado permanentemente. Contacta al administrador.'
      );
      return;
    }

    if (cleanEmail === 'admin@swaply.com') {
      if (loginPassword !== '1014Rizla@') {
        setAuthError('❌ Contraseña de administrador incorrecta.');
        return;
      }
      const session = {
        email: 'admin@swaply.com',
        username: 'Administrador',
        isGuest: false,
        isVerified: true,
      };
      setCurrentUserSession(session);
      setCurrentTab('admin');
      return;
    }

    try {
      if (auth) {
        const userCred = await signInWithEmailAndPassword(
          auth,
          cleanEmail,
          loginPassword
        );
        const firebaseVerified = userCred.user.emailVerified;
        // Prefer registered username over email prefix
        let realUsername = cleanEmail.split('@')[0];
        const regAcc = Object.values(registeredAccounts || {}).find(
          (a) => String(a.email || '').toLowerCase() === cleanEmail
        );
        if (regAcc && regAcc.username) realUsername = regAcc.username;

        let currentUsers = users;
        try {
          const savedU = localStorage.getItem('pokepop_users');
          if (savedU) currentUsers = JSON.parse(savedU);
        } catch (e) {}

        if (!currentUsers[realUsername]) {
          currentUsers = {
            ...currentUsers,
            [realUsername]: {
              name: realUsername,
              displayName: realUsername,
              photoUrl: '',
              description: '',
              location: 'España',
              rating: 5.0,
              reviews: [],
            },
          };
          setUsers(currentUsers);
          localStorage.setItem('pokepop_users', JSON.stringify(currentUsers));
        }

        const session = {
          email: cleanEmail,
          username: realUsername,
          isGuest: false,
          isVerified: firebaseVerified,
        };
        setCurrentUserSession(session);
        setCurrentTab('home');
      }
    } catch (err) {
      setAuthError(
        '❌ Correo o contraseña incorrectos, o cuenta no registrada en Firebase: ' +
          err.message
      );
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setAuthError('');

    if (!regUsername || !regEmail || !regPassword || !regConfirmPassword) {
      setAuthError(t('allFieldsRequired'));
      return;
    }

    if (regPassword !== regConfirmPassword) {
      setAuthError(t('passwordsDoNotMatch'));
      return;
    }

    if (regPassword.length < 6) {
      setAuthError(t('passwordMinLength'));
      return;
    }

    if (!regAcceptTerms) {
      setAuthError(t('mustAcceptTerms'));
      return;
    }

    const cleanEmailKey = String(regEmail).trim().toLowerCase();
    const cleanRegUserName = String(regUsername).trim();

    if (
      bannedEmails.map((e) => String(e).toLowerCase()).includes(cleanEmailKey)
    ) {
      setAuthError(
        '🚫 Este correo está baneado permanentemente y no puede crear una cuenta.'
      );
      return;
    }

    setRegLoading(true);
    let approxLoc = {
      location: t('approxAreaFallback'),
      lat: null,
      lon: null,
    };
    try {
      approxLoc = await detectUserApproxLocation();
    } catch (e) {}

    try {
      if (auth) {
        const userCredential = await createUserWithEmailAndPassword(
          auth,
          cleanEmailKey,
          regPassword
        );
        await sendEmailVerification(userCredential.user);
      }
    } catch (error) {
      setRegLoading(false);
      setAuthError('Error en Firebase Auth: ' + error.message);
      return;
    }

    let currentUsers = users;
    try {
      const savedU = localStorage.getItem('pokepop_users');
      if (savedU) currentUsers = JSON.parse(savedU);
    } catch (e) {}

    const newUser = {
      name: cleanRegUserName,
      displayName: cleanRegUserName,
      photoUrl: '',
      description: '',
      email: cleanEmailKey,
      location: approxLoc.location || t('approxAreaFallback'),
      lat: approxLoc.lat,
      lon: approxLoc.lon,
      countryCode: approxLoc.countryCode || '',
      rating: 5.0,
      reviews: [],
      acceptedTermsAt: new Date().toISOString(),
      acceptedTermsVersion: '1.0',
    };

    const updatedUsers = { ...currentUsers, [cleanRegUserName]: newUser };
    setUsers(updatedUsers);
    localStorage.setItem('pokepop_users', JSON.stringify(updatedUsers));

    // 1 cuenta por email: sobrescribe si ya existía (borrar + volver a registrar = 1 usuario)
    let currentAccounts = {};
    try {
      const savedAcc = localStorage.getItem('pokepop_registered_accounts');
      if (savedAcc) currentAccounts = JSON.parse(savedAcc) || {};
    } catch (e) {}
    currentAccounts[cleanEmailKey] = {
      username: cleanRegUserName,
      email: cleanEmailKey,
      location: newUser.location,
      isVerified: false,
      banned: false,
      acceptedTermsAt: newUser.acceptedTermsAt,
      acceptedTermsVersion: '1.0',
    };
    setRegisteredAccounts(currentAccounts);
    localStorage.setItem(
      'pokepop_registered_accounts',
      JSON.stringify(currentAccounts)
    );

    if (approxLoc.lat != null && approxLoc.lon != null) {
      const coords = { lat: approxLoc.lat, lon: approxLoc.lon };
      setUserCoords(coords);
      try {
        localStorage.setItem('pokepop_user_coords', JSON.stringify(coords));
      } catch (e) {}
    }

    const session = {
      email: cleanEmailKey,
      username: cleanRegUserName,
      isGuest: false,
      isVerified: false,
    };
    setCurrentUserSession(session);
    setCurrentTab('home');
    setRegLoading(false);

    alert(t('accountCreatedAlert'));
  };

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    if (!forgotEmail.trim()) return;
    try {
      if (auth) {
        await sendPasswordResetEmail(auth, forgotEmail.trim());
      }
      alert(
        `📧 ¡Correo de restablecimiento enviado correctamente por Firebase a ${forgotEmail}! Revisa tu bandeja.`
      );
    } catch (err) {
      alert('❌ Error al enviar el correo con Firebase: ' + err.message);
    }
    setForgotEmail('');
    setShowForgotPasswordModal(false);
  };

  const handleGuestLogin = () => {
    const session = {
      email: 'guest@swaply.com',
      username: 'Invitado',
      isGuest: true,
      isVerified: false,
    };
    setCurrentUserSession(session);
    setCurrentTab('home');
  };

  const handleSimulateVerifyEmail = () => {
    const emailKey = String(currentUserSession?.email || '')
      .trim()
      .toLowerCase();
    if (!emailKey) return;

    let currentAccounts = registeredAccounts;
    try {
      const savedAcc = localStorage.getItem('pokepop_registered_accounts');
      if (savedAcc) currentAccounts = JSON.parse(savedAcc);
    } catch (e) {}

    if (currentAccounts[emailKey]) {
      currentAccounts[emailKey].isVerified = true;
      setRegisteredAccounts(currentAccounts);
      localStorage.setItem(
        'pokepop_registered_accounts',
        JSON.stringify(currentAccounts)
      );
    }

    const updatedSession = { ...currentUserSession, isVerified: true };
    setCurrentUserSession(updatedSession);

    alert('✅ ' + t('emailConfirmedUnlocked'));
  };

  /** Ubicación siempre automática (~10 km de privacidad); no editable por el usuario */
  const ensureAutoLocationForUser = async (username) => {
    if (!username) return;
    let currentUsers = users;
    try {
      const savedU = localStorage.getItem('pokepop_users');
      if (savedU) currentUsers = JSON.parse(savedU);
    } catch (e) {}
    const existing = currentUsers[username];
    if (existing?.lat != null && existing?.lon != null && existing?.location) {
      return;
    }
    try {
      const approxLoc = await detectUserApproxLocation();
      const updated = {
        ...(existing || {
          name: username,
          displayName: username,
          photoUrl: '',
          description: '',
          rating: 5.0,
          reviews: [],
        }),
        location:
          approxLoc.location || existing?.location || t('approxAreaFallback'),
        lat: approxLoc.lat,
        lon: approxLoc.lon,
        countryCode: approxLoc.countryCode || existing?.countryCode || '',
      };
      const nextUsers = { ...currentUsers, [username]: updated };
      setUsers(nextUsers);
      localStorage.setItem('pokepop_users', JSON.stringify(nextUsers));
      if (approxLoc.lat != null && approxLoc.lon != null) {
        const coords = { lat: approxLoc.lat, lon: approxLoc.lon };
        setUserCoords(coords);
        try {
          localStorage.setItem('pokepop_user_coords', JSON.stringify(coords));
        } catch (e) {}
      }
    } catch (e) {}
  };

  const handleLogout = () => {
    setActiveChatId(null);
    setCurrentUserSession(null);
  };

  const handleDeleteAccount = async () => {
    try {
      if (auth && auth.currentUser) {
        await auth.currentUser.delete();
      }
    } catch (err) {
      console.warn('Firebase Auth delete notice:', err);
    }

    let currentUsers = users;
    try {
      const savedU = localStorage.getItem('pokepop_users');
      if (savedU) currentUsers = JSON.parse(savedU);
    } catch (e) {}

    if (currentUsername && currentUsers[currentUsername]) {
      delete currentUsers[currentUsername];
      setUsers(currentUsers);
      localStorage.setItem('pokepop_users', JSON.stringify(currentUsers));
    }

    // Quitar de cuentas registradas por email (si se vuelve a registrar contará como 1)
    try {
      const emailKey = String(
        currentUserSession?.email ||
          currentUsers?.[currentUsername]?.email ||
          ''
      )
        .trim()
        .toLowerCase();
      let currentAccounts = {};
      const savedAcc = localStorage.getItem('pokepop_registered_accounts');
      if (savedAcc) currentAccounts = JSON.parse(savedAcc) || {};
      if (emailKey && currentAccounts[emailKey]) {
        delete currentAccounts[emailKey];
      }
      // También limpiar entradas residuales del mismo username
      for (const [k, acc] of Object.entries({ ...currentAccounts })) {
        if (
          String(acc?.username || '').toLowerCase() ===
          String(currentUsername || '').toLowerCase()
        ) {
          delete currentAccounts[k];
        }
      }
      setRegisteredAccounts(currentAccounts);
      localStorage.setItem(
        'pokepop_registered_accounts',
        JSON.stringify(currentAccounts)
      );
    } catch (e) {}

    const nextProducts = products.filter(
      (p) =>
        String(p.sellerUsername || '').toLowerCase() !==
          currentUsername.toLowerCase() &&
        String(p.seller || '').toLowerCase() !==
          currentUsername.toLowerCase() &&
        String(p.seller || '').toLowerCase() !==
          displayTrainerName.toLowerCase()
    );

    const nextChats = chats.filter((c) => {
      const buyerUser = String(c.buyerUsername || c.buyer || '').toLowerCase();
      const sellerUser = String(
        c.sellerUsername || c.seller || ''
      ).toLowerCase();
      const currentStr = currentUsername.toLowerCase();
      return buyerUser !== currentStr && sellerUser !== currentStr;
    });

    const nextPurchases = confirmedPurchases.filter(
      (p) =>
        String(p.buyer || '').toLowerCase() !== currentUsername.toLowerCase() &&
        String(p.seller || '').toLowerCase() !== currentUsername.toLowerCase()
    );

    saveToStorage(nextChats, nextPurchases, null, nextProducts);

    setShowDeleteAccountModal(false);
    handleLogout();
    alert(t('deleteAccountAlert'));
  };

  const handleDeleteProduct = (productId) => {
    if (
      window.confirm(
        '¿Estás seguro de que deseas eliminar este anuncio permanentemente?'
      )
    ) {
      const nextProducts = products.filter((p) => p.id !== productId);
      saveToStorage(null, null, null, nextProducts);
      setSelectedProduct(null);
      alert('🗑️ ' + t('adDeletedSuccess'));
    }
  };

  const handleCreateFakeProduct = async () => {
    if (!fakeTitle || !String(fakeTitle).trim()) {
      alert('⚠️ ' + t('fakeTitleRequired'));
      return;
    }

    const count = Math.max(1, Math.min(200, Number(fakeBulkCount) || 1));
    const autoWorld = fakeBulkAutoWorld && count > 1;

    if (
      !autoWorld &&
      (!fakeMapPick || fakeMapPick.lat == null || fakeMapPick.lon == null)
    ) {
      alert('⚠️ ' + t('selectMapBeforePublish'));
      setShowFakeMapModal(true);
      return;
    }

    setFakePublishing(true);
    try {
      const originalTitle = String(fakeTitle).trim();
      const originalDesc =
        String(fakeDescription || '').trim() ||
        'Artículo de colección en gran estado.';
      const catMeta = PRODUCT_CATEGORIES.find((c) => c.id === fakeCategory);
      const originalCategory = catMeta ? t(catMeta.labelKey) : 'Cartas TCG';
      const subMeta = TCG_SUBCATEGORIES.find((s) => s.id === fakeSubcategory);
      const originalSubcategory =
        fakeCategory === 'cartas-tcg' && subMeta ? t(subMeta.labelKey) : null;
      const originalCondition = 'Como nuevo';
      const eurPrice = fakePrice ? Number(fakePrice) : 25;

      const finalImages =
        fakeImages.length > 0
          ? fakeImages
          : [
              'https://images.unsplash.com/photo-1613771404784-3a5686aa2be3?w=600',
            ];

      const newProducts = [];
      const usedCities = [];

      for (let i = 0; i < count; i++) {
        let pick;
        if (autoWorld) {
          // Pick a random city, avoid exact repeats when possible
          let city;
          const available = WORLD_CITIES.filter(
            (c) => !usedCities.includes(c.name)
          );
          const pool = available.length > 0 ? available : WORLD_CITIES;
          city = pool[Math.floor(Math.random() * pool.length)];
          usedCities.push(city.name);
          // Small random offset so they don't stack exactly
          const latOff = (Math.random() - 0.5) * 0.3;
          const lonOff = (Math.random() - 0.5) * 0.3;
          pick = {
            lat: city.lat + latOff,
            lon: city.lon + lonOff,
            location: city.name,
            countryCode: city.country,
            lang: city.lang,
            currency: {
              code: city.currency,
              symbol: city.currency === 'EUR' ? '€' : city.currency,
            },
          };
        } else {
          pick = fakeMapPick;
        }

        const targetLang =
          pick.lang || getLangFromCountryCode(pick.countryCode) || 'en';
        const localCurrency =
          pick.currency ||
          getCurrencyFromCountryCode(pick.countryCode) ||
          CURRENCIES.EUR;

        const [titleTx, descTx, catTx, condTx, convertedPrice] =
          await Promise.all([
            translateFromSpanish(originalTitle, targetLang),
            translateFromSpanish(originalDesc, targetLang),
            translateFromSpanish(originalCategory, targetLang),
            translateFromSpanish(originalCondition, targetLang),
            convertEurToCurrency(eurPrice, localCurrency.code),
          ]);

        const fullLoc =
          pick.location ||
          `${Number(pick.lat).toFixed(4)}, ${Number(pick.lon).toFixed(4)}`;

        let sellerName = String(fakeSellerName || 'Oak_Collector').trim();
        if (fakeRandomSeller && count > 1) {
          sellerName = getRandomSellerForCountry(pick.countryCode);
        }

        const newFakeProd = {
          id:
            'fake_' +
            Date.now() +
            '_' +
            i +
            '_' +
            Math.random().toString(36).slice(2, 6),
          title: titleTx,
          price: convertedPrice,
          category: fakeCategory,
          categoryLabel: catTx,
          subcategory: fakeCategory === 'cartas-tcg' ? fakeSubcategory : null,
          subcategoryLabel: originalSubcategory,
          condition: condTx,
          location: fullLoc,
          imageUrl: finalImages[0],
          images: finalImages,
          description: descTx,
          seller: sellerName,
          sellerUsername: sellerName.toLowerCase().replace(/\s+/g, '_'),
          status: 'Disponible',
          lat: pick.lat,
          lon: pick.lon,
          countryCode: pick.countryCode || '',
          currency: localCurrency.code,
          currencySymbol: localCurrency.symbol || localCurrency.code,
          acceptTrade: !!fakeAcceptTrade,
          isGraded: !!fakeIsGraded,
          gradeScore:
            fakeIsGraded && fakeGradeScore ? Number(fakeGradeScore) : null,
        };
        newProducts.push(newFakeProd);
      }

      const nextProducts = [...newProducts, ...products];
      saveToStorage(null, null, null, nextProducts);
      setFakeTitle('');
      setFakePrice('');
      setFakeDescription('');
      setFakeImages([]);
      setFakeBulkCount(1);
      setFakeBulkAutoWorld(false);
      setFakeAcceptTrade(false);
      setFakeIsGraded(false);
      setFakeGradeScore('');
      alert(
        `✅ ${newProducts.length} anuncio(s) de relleno creado(s)${
          autoWorld ? ' en distintas ubicaciones del mundo' : ''
        }.`
      );
    } catch (err) {
      alert(
        '❌ Error al publicar el anuncio de relleno: ' + (err.message || err)
      );
    }
    setFakePublishing(false);
  };

  const handleDeleteAllFakeProducts = () => {
    const fakeCount = products.filter((p) =>
      String(p.id).startsWith('fake_')
    ).length;
    if (fakeCount === 0) {
      alert('No hay anuncios falsos para borrar.');
      return;
    }
    if (
      window.confirm(
        `⚠️ ¿Seguro que quieres borrar los ${fakeCount} anuncios falsos de relleno?`
      )
    ) {
      const nextProducts = products.filter(
        (p) => !String(p.id).startsWith('fake_')
      );
      saveToStorage(null, null, null, nextProducts);
      alert(`🗑️ Se han eliminado ${fakeCount} anuncios falsos.`);
    }
  };

  const handleDeleteAllProducts = () => {
    if (
      window.confirm(
        '⚠️ ¿Estás COMPLETAMENTE SEGURO de que deseas borrar TODOS los anuncios de la plataforma?'
      )
    ) {
      saveToStorage(null, null, null, []);
      alert('🗑️ Todos los anuncios han sido eliminados.');
    }
  };

  const handleBanUser = (targetEmailOrUsername) => {
    let targetEmail = String(targetEmailOrUsername || '')
      .trim()
      .toLowerCase();
    // Resolve real email from registeredAccounts if we received a username
    if (!targetEmail.includes('@')) {
      const acc = Object.values(registeredAccounts || {}).find(
        (a) => String(a.username || '').toLowerCase() === targetEmail
      );
      if (acc && acc.email)
        targetEmail = String(acc.email).trim().toLowerCase();
    }
    if (
      window.confirm(
        `¿Estás seguro de banear el correo ${targetEmail} y eliminar sus anuncios?`
      )
    ) {
      let currentBanned = bannedEmails;
      if (!currentBanned.includes(targetEmail)) {
        const nextBanned = [...currentBanned, targetEmail];
        setBannedEmails(nextBanned);
        localStorage.setItem(
          'pokepop_banned_emails',
          JSON.stringify(nextBanned)
        );
      }

      const nextProducts = products.filter((p) => {
        const pSellerName = String(p.seller || '').toLowerCase();
        return pSellerName !== targetEmail.split('@')[0];
      });
      saveToStorage(null, null, null, nextProducts);

      setViewingSellerProfile(null);
      alert(
        `🔨 Correo electrónico ${targetEmail} baneado permanentemente y anuncios eliminados.`
      );
    }
  };

  const handleUnbanEmail = (emailToUnban) => {
    if (
      window.confirm(
        `¿Estás seguro de quitar el baneo al correo ${emailToUnban}?`
      )
    ) {
      const nextBanned = bannedEmails.filter(
        (b) =>
          String(typeof b === 'string' ? b : b.email).toLowerCase() !==
          String(emailToUnban).toLowerCase()
      );
      setBannedEmails(nextBanned);
      localStorage.setItem('pokepop_banned_emails', JSON.stringify(nextBanned));
      alert(`🔓 El correo ${emailToUnban} ha sido desbaneado con éxito.`);
    }
  };

  const handleDeleteRegisteredAccount = (targetEmail, targetUsername) => {
    if (
      window.confirm(
        `⚠️ ¿Estás seguro de que deseas eliminar permanentemente la cuenta de ${targetUsername} (${targetEmail}) y todos sus datos?`
      )
    ) {
      const cleanEmailKey = String(targetEmail || '')
        .trim()
        .toLowerCase();
      const cleanUsernameStr = String(targetUsername || '')
        .trim()
        .toLowerCase();

      let currentAccounts = { ...registeredAccounts };
      try {
        const savedAcc = localStorage.getItem('pokepop_registered_accounts');
        if (savedAcc) currentAccounts = JSON.parse(savedAcc);
      } catch (e) {}

      let keyToDelete = '';
      for (const [k, acc] of Object.entries(currentAccounts)) {
        const accEmail = String(acc.email || k)
          .trim()
          .toLowerCase();
        const accUser = String(acc.username || '')
          .trim()
          .toLowerCase();
        if (accEmail === cleanEmailKey || accUser === cleanUsernameStr) {
          keyToDelete = k;
          break;
        }
      }

      if (keyToDelete && currentAccounts[keyToDelete]) {
        delete currentAccounts[keyToDelete];
      }
      if (currentAccounts[cleanEmailKey]) {
        delete currentAccounts[cleanEmailKey];
      }

      const uniqueAccounts = {};
      for (const [k, acc] of Object.entries(currentAccounts)) {
        const eKey = String(acc.email || k)
          .trim()
          .toLowerCase();
        if (eKey && eKey !== cleanEmailKey && !uniqueAccounts[eKey]) {
          uniqueAccounts[eKey] = { ...acc, email: eKey };
        }
      }

      setRegisteredAccounts(uniqueAccounts);
      localStorage.setItem(
        'pokepop_registered_accounts',
        JSON.stringify(uniqueAccounts)
      );

      let currentUsers = { ...users };
      try {
        const savedU = localStorage.getItem('pokepop_users');
        if (savedU) currentUsers = JSON.parse(savedU);
      } catch (e) {}

      for (const [uName] of Object.entries(currentUsers)) {
        if (uName.toLowerCase() === cleanUsernameStr) {
          delete currentUsers[uName];
        }
      }
      setUsers(currentUsers);
      localStorage.setItem('pokepop_users', JSON.stringify(currentUsers));

      const nextProducts = products.filter((p) => {
        const pSellerUser = String(p.sellerUsername || '')
          .trim()
          .toLowerCase();
        const pSellerName = String(p.seller || '')
          .trim()
          .toLowerCase();
        return (
          pSellerUser !== cleanUsernameStr && pSellerName !== cleanUsernameStr
        );
      });
      saveToStorage(null, null, null, nextProducts);

      alert(
        `🗑️ La cuenta de ${targetUsername} (${targetEmail}) ha sido eliminada permanentemente del sistema.`
      );
    }
  };

  const handleMultipleImagesUpload = (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 0) {
      const newUrls = files.map((file) => URL.createObjectURL(file));
      setImageUrls((prev) => [...prev, ...newUrls].slice(0, 4));
    }
  };

  const handleProfilePhotoUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      setEditPhotoUrl(URL.createObjectURL(file));
    }
  };

  const handleSaveProfile = (e) => {
    e.preventDefault();
    const oldDisplayName = String(
      currentUserData.displayName || currentUsername
    );
    const newDisplayName = String(editDisplayName || currentUsername).trim();
    const newPhotoUrl = editPhotoUrl;
    const cleanDescription = String(editDescription || '')
      .trim()
      .slice(0, 500);

    // La ubicación es automática y no editable (privacidad ~10 km)
    const updatedUser = {
      ...currentUserData,
      displayName: newDisplayName,
      description: cleanDescription,
      photoUrl: newPhotoUrl,
    };

    const updatedUsers = { ...users, [currentUsername]: updatedUser };
    setUsers(updatedUsers);
    localStorage.setItem('pokepop_users', JSON.stringify(updatedUsers));

    const updatedProducts = products.map((p) => {
      const isAuthor =
        String(p.sellerUsername || '').toLowerCase() ===
          currentUsername.toLowerCase() ||
        String(p.seller || '').toLowerCase() === oldDisplayName.toLowerCase();
      if (isAuthor) {
        return {
          ...p,
          seller: newDisplayName,
          sellerUsername: currentUsername,
        };
      }
      return p;
    });
    saveToStorage(null, null, null, updatedProducts);

    setShowProfileEditor(false);
    alert(t('profileUpdatedSuccess'));
  };

  const handleSendReport = () => {
    if (isGuest) {
      alert('🔒 ' + t('guestsCannotReport'));
      return;
    }
    const cleanReason = String(reportReason || '').trim();
    if (!cleanReason) {
      alert('⚠️ ' + t('writeReportReason'));
      return;
    }

    const targetName = reportingItem?.name || 'Anuncio/Usuario';
    const targetType = reportingItem?.type || 'product';

    const newId = 'rep_' + Date.now();
    const reportData = {
      id: newId,
      type: targetType,
      target: targetName,
      reason: cleanReason,
      reporter: currentUsername,
      timestamp: new Date().toISOString(),
    };

    const nextReports = [reportData, ...adminReports];
    setAdminReports(nextReports);
    localStorage.setItem('pokepop_admin_reports', JSON.stringify(nextReports));

    try {
      const nextUnreadRep = Array.isArray(unreadReportIds)
        ? [...unreadReportIds, newId]
        : [newId];
      setUnreadReportIds(nextUnreadRep);
      localStorage.setItem(
        'pokepop_unread_reports',
        JSON.stringify(nextUnreadRep)
      );
    } catch (e) {}

    setReportReason('');
    setReportingItem(null);
    alert('✅ ' + t('reportSentSuccess'));
  };

